import {seasons,endings,choiceLabel,resolveEnding,endingText,statusFor} from './model.mjs';
import {cleanState,freshState} from './state.mjs';
import * as cloud from './cloud.mjs';
import * as music from './music.mjs';
import {regions,worldSVG,changeCaption} from './world.mjs';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const H=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const spots=[[25,27],[43,48],[73,33],[77,73]],icons=['🌳','💧','🌾','🏮'];
const descriptions=[['도로를 가장 짧게 연결해요.','이미 있는 도로를 이용해요.','조사하고 이동 통로를 마련해요.','숲 일부를 꽃밭으로 꾸며요.'],['처리 시설을 수리하고 점검해요.','물가에 모인 쓰레기를 주워요.','축제장에 가림막과 조명을 설치해요.','세 가지 대책에 예산을 나눠요.'],['피해 구역을 확인하고 관리해요.','농장 전체에 농약을 사용해요.','작물과 풀 대신 한 종류의 꽃을 심어요.','이번에는 관리하지 않고 지켜봐요.'],['컵 반납함과 분리배출함을 준비해요.','행사 뒤 청소 시간을 정해요.','일회용품과 조명을 준비해요.','모은 쓰레기를 태워 처리해요.']];
let key='eco-village-guest-v2',state=readLocal(),selected=null,visited=0,budget=[null,null,null],picked=null,scope=25,placed=[],work=null,lastDrop=0,toastTimer,cinemaTimer,cloudStatus='guest',booting=cloud.configured,viewMode='auto',pastChapter=null;
function readLocal(){try{return cleanState(JSON.parse(localStorage.getItem(key)||'null'));}catch{return freshState();}}
function writeLocal(){try{localStorage.setItem(key,JSON.stringify(state));if(cloud.account())localStorage.setItem(key+'-base',String(cloud.version()));}catch{toast('기기 저장 공간이 부족해요.');}}
function save(){state.updatedAt=Date.now();writeLocal();cloud.queueCloud(state);}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2400);}
function reset(){selected=null;visited=0;budget=[null,null,null];picked=null;scope=25;placed=[];}
const g=()=>state.game, count=()=>Object.keys(state.album).length;
function header(){const a=cloud.account();return `<header class="topbar"><button class="logo" id="home" aria-label="처음 화면"><span>🌿</span> 초록마을의 네 계절</button><nav class="seasons" aria-label="계절 진행">${seasons.map((s,i)=>`<span class="season ${g()?.stage===i?'active':''} ${g()?.choices[i]?'complete':''}">${icons[i]} ${s.name}${g()?.choices[i]?' ✓':''}</span>`).join('')}</nav><div class="top-actions">${musicUI()}<button id="save-cloud" class="save-state" title="진행 기록 저장">${cloudLabel()}</button><button id="account" class="icon-button" aria-label="학교 계정">${a?H(a.nickname||'주민'):'학교 계정'}</button><button id="album" class="icon-button" aria-label="엔딩 앨범">📖 ${count()}/10</button><button id="help" class="icon-button" aria-label="게임 방법">?</button></div></header>`;}
function cloudLabel(){return ({guest:'기기에 저장',online:'온라인 연결',saved:'☁ 저장 완료',pending:'☁ 저장 대기',saving:'☁ 저장 중',error:'☁ 다시 저장',conflict:'☁ 다른 기기 기록'})[cloudStatus]||'기기에 저장';}
function musicUI(){return `<span class="music-controls"><button class="icon-button music-toggle" data-music-toggle aria-label="배경음악 켜기" aria-pressed="false" title="배경음악 켜기">🔇</button><button class="icon-button music-settings" data-music-settings aria-label="배경음악 음량 설정" title="배경음악 음량 설정">♫</button></span>`;}
function updateMusic(){const s=music.status();$$('[data-music-toggle]').forEach(b=>{b.textContent=s.loading?'…':s.enabled?'🔊':'🔇';b.setAttribute('aria-pressed',String(s.enabled));b.setAttribute('aria-label',s.enabled?'배경음악 끄기':'배경음악 켜기');b.title=s.enabled?'배경음악 끄기':'배경음악 켜기';});const v=$('#music-volume-label');if(v)v.textContent=Math.round(s.volume*100)+'%';const t=$('#music-title');if(t)t.textContent=s.loading?'음악을 준비하고 있어요…':s.enabled?s.title:'배경음악이 꺼져 있어요.';}
function bindMusic(){updateMusic();$$('[data-music-toggle]').forEach(b=>b.onclick=()=>music.setEnabled(!music.status().enabled).catch(()=>toast('음악을 불러오지 못했어요. 소리 버튼을 다시 눌러 주세요.')));$$('[data-music-settings]').forEach(b=>b.onclick=musicDialog);}
function musicDialog(){const s=music.status();modal('♫ 마을의 배경음악',`<div class="music-panel"><p id="music-title">${s.enabled?s.title:'배경음악이 꺼져 있어요.'}</p><button class="secondary" data-music-toggle aria-label="배경음악 켜기"></button><label for="music-volume">음량 <strong id="music-volume-label">${Math.round(s.volume*100)}%</strong></label><input id="music-volume" type="range" min="0" max="100" step="5" value="${Math.round(s.volume*100)}" aria-label="배경음악 음량"><p class="small-note">소리 버튼으로 켜고 끌 수 있어요. 음량은 이 기기에 기억해요.<br>새로 열면 소리는 꺼져 있어요.</p><p class="small-note">마을과 엔딩을 위해 직접 만든 무료 곡이에요.<br>「초록마을 산책」 · 「우리의 다음 봄」 · 「돌아오지 않는 봄」</p></div>`);bindMusic();$('#music-volume').oninput=e=>music.setVolume(Number(e.target.value)/100);}
music.subscribe(updateMusic);
function bindHeader(){bindMusic();$('#home').onclick=home;$('#album').onclick=openAlbum;$('#help').onclick=help;$('#account').onclick=accountDialog;$('#save-cloud').onclick=async()=>{if(!cloud.account()){accountDialog();return;}if(cloudStatus==='conflict'){conflictDialog();return;}try{cloud.queueCloud(state);await cloud.flushCloud();toast('온라인에 저장했어요. 다른 기기에서도 이어 할 수 있어요.');}catch{toast('연결을 확인해 주세요. 기기 기록은 남아 있어요.');}};}
function home(){pastChapter=null;viewMode='auto';music.setScene('village');clearInterval(cinemaTimer);$('.cinema')?.remove();$('#dialog').close();$('#app').innerHTML=header()+`<main class="home-screen"><div class="home-art"></div><section class="welcome parchment"><span class="eyebrow">생태계 이야기 모험</span><h1>초록마을의<br>네 계절</h1><p>작은 마을의 주민이 되어<br>숲과 하천, 농장과 축제를 만나 보세요.</p><div class="welcome-badges"><span>네 계절의 선택</span><span>10개의 엔딩</span></div><div class="welcome-actions">${g()?'<button class="primary" id="continue">모험 이어 하기</button>':''}<button class="${g()?'secondary':'primary'}" id="new-game">새 모험 시작</button><button class="text-button" id="login-start">학교 계정으로 기록 남기기</button></div><small>지도를 누르거나 방향키로 움직여요.<br>다른 선택으로 새로운 엔딩을 모아 보세요.</small></section><div class="home-note">🌿 같은 마을, 서로 다른 내일</div></main>`;bindHeader();$('#new-game').onclick=()=>start(0);$('#login-start').onclick=accountDialog;if($('#continue'))$('#continue').onclick=render;if(booting){$('#new-game').disabled=true;if($('#continue'))$('#continue').disabled=true;}}
function start(stage){if(booting){toast('기록을 확인하고 있어요. 잠시만 기다려 주세요.');return;}clearInterval(cinemaTimer);$('.cinema')?.remove();$('#dialog').close();const previous=state.last;if(stage&& !previous){toast('먼저 한 판을 끝내 주세요.');return;}viewMode='map';pastChapter=null;state.game={stage,choices:stage?previous.choices.map((v,i)=>i<stage?v:null):[null,null,null,null],phase:'explore',player:[50,65]};reset();save();render();}
function playerHTML(){return `<div class="explorer" id="explorer" style="left:${g().player[0]}%;top:${g().player[1]}%" role="img" aria-label="내 캐릭터"><span class="explorer-hair"></span><span class="explorer-face"></span><span class="explorer-shirt"></span><span class="explorer-feet"></span><span class="explorer-name">${H(cloud.account()?.nickname||'나')}</span></div>`;}
function mapHTML(){
  const current=Math.min(g().stage,3),s=seasons[current],done=g().stage===4;
  return `<section class="map-frame" aria-label="초록마을 이동 지도"><div class="world-plane">${worldSVG({choices:g().choices,stage:g().stage})}<div class="map-glow"></div>${seasons.map((season,i)=>`<button class="village-spot ${i===current&&!done?'current':''} ${g().choices[i]?'recorded':''}" data-spot="${i}" style="left:${spots[i][0]}%;top:${spots[i][1]}%"><span>${icons[i]}</span><strong>${season.area}</strong><small>${g().choices[i]?changeCaption(g().choices,i):i===current?season.speaker+' 만나기':'아직 오지 않은 계절'}</small>${g().choices[i]?'<i>✓</i>':i===current?'<i>!</i>':''}</button>`).join('')}${playerHTML()}</div><div class="map-name">${icons[current]} ${s.month} · 초록마을 전체 지도</div><div class="travel-guide"><span>${done?'🏡':icons[current]}</span><div><small>${done?'네 계절의 선택이 모였어요':s.name+' · '+s.title}</small><strong>${done?'다음 봄을 앞둔 마을 회의':s.area+'에서 '+s.speaker+' 만나기'}</strong></div><button id="enter-chapter">${done?'마을 회의':g().phase==='result'?'변화 보기':'장소로 이동'} →</button></div><div class="map-dock"><div class="arrows" aria-label="캐릭터 이동"><button data-move="up" aria-label="위로 이동">▲</button><button data-move="left" aria-label="왼쪽 이동">◀</button><button data-move="down" aria-label="아래로 이동">▼</button><button data-move="right" aria-label="오른쪽 이동">▶</button></div><button id="journal" class="journal-button">🎒 내 모험 기록 <span>${g().choices.filter(Boolean).length}/4</span></button><span class="movement-tip">지도 터치 · 방향키 이동</span></div></section>`;
}
function render(){
  if(!g()){home();return;}
  music.setScene('village');clearInterval(cinemaTimer);$('.cinema')?.remove();
  const chapter=viewMode==='chapter'||(viewMode==='auto'&&g().phase!=='explore');
  $('#app').innerHTML=header()+`<main class="${chapter?'chapter-screen':'travel-screen'}">${chapter?chapterHTML():mapHTML()}</main>`;
  bindHeader();
  if(chapter){$('#back-map').onclick=()=>{viewMode='map';pastChapter=null;render();};renderQuest();}
  else bindMap();
}
function chapterHTML(){
  const i=pastChapter??Math.min(g().stage,3),s=seasons[i],isResult=pastChapter!==null||g().phase==='result',meeting=g().stage===4&&pastChapter===null;
  return `<section class="chapter-scene" aria-label="${s.area}의 배경">${worldSVG({choices:g().choices,chapter:meeting?null:i,stage:g().stage})}</section><div class="chapter-banner"><small>${meeting?'네 계절의 마지막 장':'CHAPTER '+(i+1)+' · '+s.name.toUpperCase()}</small><h1>${meeting?'마을 회의':regions[i].name}</h1><p>${pastChapter!==null?'내 선택이 남긴 풍경':s.month+' · '+s.speaker+'의 이야기'}</p></div><button class="chapter-back" id="back-map">↖ 전체 지도로</button>${isResult?`<div class="scene-change-note">${icons[i]} ${changeCaption(g().choices,i)}</div>`:''}<div id="route-work"></div><section class="quest parchment ${isResult?'result-panel':meeting?'final-panel':''}" id="quest" aria-label="${meeting?'마을 회의':s.speaker+'의 대화와 선택'}"></section>`;
}
function enterChapter(i=g().stage,past=false){
  pastChapter=past?i:null;viewMode='chapter';
  if(!past&&g().phase==='explore'){g().player=[spots[i][0],spots[i][1]+10];g().phase='task';save();}
  render();
}
function bindMap(){
  $$('[data-spot]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.spot);if(g().choices[i]){enterChapter(i,i!==g().stage);return;}if(i===g().stage)enterChapter(i);else toast('모험은 봄부터 순서대로 이어져요.');});
  $('.world-plane').onclick=e=>{if(e.target.closest('button'))return;const r=e.currentTarget.getBoundingClientRect();moveTo((e.clientX-r.left)/r.width*100,(e.clientY-r.top)/r.height*100);};
  $$('[data-move]').forEach(b=>b.onclick=()=>move(b.dataset.move));$('#journal').onclick=journal;$('#enter-chapter').onclick=()=>enterChapter();
}
function moveTo(x,y){
  if(!$('#explorer'))return;
  g().player=[Math.max(7,Math.min(93,x)),Math.max(9,Math.min(85,y))];
  const p=$('#explorer');if(p){p.style.left=g().player[0]+'%';p.style.top=g().player[1]+'%';p.classList.add('walking');setTimeout(()=>p.classList.remove('walking'),550);}
  try{localStorage.setItem(key,JSON.stringify(state));}catch{}
  if(g().stage<4&&!g().choices[g().stage]){const s=spots[g().stage];if(Math.hypot(g().player[0]-s[0],g().player[1]-s[1])<13)enterChapter();}
}
function move(direction){const delta=({left:[-4,0],right:[4,0],up:[0,-4],down:[0,4]})[direction];if(g()&&delta)moveTo(g().player[0]+delta[0],g().player[1]+delta[1]);}
document.addEventListener('keydown',e=>{if($('#dialog').open||$('.cinema')||!g()||e.target.matches('input,textarea,button'))return;const dir=({ArrowLeft:'left',ArrowRight:'right',ArrowUp:'up',ArrowDown:'down',a:'left',d:'right',w:'up',s:'down'})[e.key];if(dir){e.preventDefault();move(dir);}});
function renderQuest(){
  const i=pastChapter??Math.min(g().stage,3),s=seasons[i],q=$('#quest');
  if(pastChapter!==null){const c=s.choices.find(c=>c.id===g().choices[i]);q.classList.add('result-panel');q.innerHTML=`<span class="quest-tag">${s.name}에 남긴 기록</span><h2>${c.name}</h2><p class="result-text">${H(c.result)}</p><div class="result-stamp">이 선택이 지금 지도에 남아 있어요.</div><button class="primary" id="return-map">전체 지도 보기</button>`;$('#return-map').onclick=()=>{viewMode='map';pastChapter=null;render();};return;}
  if(g().stage===4||g().phase==='final'){q.classList.add('final-panel');final();return;}
  if(g().phase==='result'){
    const c=s.choices.find(c=>c.id===g().choices[g().stage]);q.classList.add('result-panel');
    q.innerHTML=`<span class="quest-tag">${s.speaker} · 선택이 남긴 변화</span><h2>${c.name}</h2><p class="result-text">${H(c.result)}</p><div class="result-stamp">📌 이 풍경은 전체 지도에도 남아요.</div><button class="secondary" id="see-world">바뀐 전체 지도 보기</button><button class="primary" id="next">${g().stage===3?'마을 회의로':'다음 계절로'}</button>`;
    $('#see-world').onclick=()=>{viewMode='map';render();};$('#next').onclick=()=>{g().stage++;g().phase=g().stage===4?'final':'explore';g().player=[50,65];viewMode=g().stage===4?'chapter':'map';pastChapter=null;reset();save();render();};return;
  }
  q.classList.remove('result-panel','final-panel');
  q.innerHTML=`<div class="quest-heading"><span class="speaker-badge">${icons[i]}</span><div><span class="quest-tag">${s.month} · ${s.speaker}의 부탁</span><h2>${s.title}</h2></div></div><p class="dialogue">“${H(s.line)}”</p><div class="task-area"><p class="instruction">${i===1?'예산 토큰 3개를 놓아 주세요.':i===0?'계획을 고른 뒤 풍경 위 번호를 이어 주세요.':i===2?'방법과 관리할 범위를 골라 주세요.':'방법을 고르고 준비물 3개를 놓아 주세요.'}</p>${i===1?budgetHTML():`<div class="choices">${s.choices.map((c,j)=>`<button class="choice ${selected===c.id?'selected':''}" data-plan="${c.id}"><span>${j+1}</span><div><strong>${c.name}</strong><small>${descriptions[i][j]}</small></div></button>`).join('')}</div>`}<div id="work"></div></div><div class="quest-footer"><p id="task-note">${selected?'준비한 방법을 실행해 보세요.':'어떤 방법을 고를까요?'}</p><div><button class="secondary" id="reset">다시 준비</button><button class="primary" id="commit" disabled>실행하기</button></div></div>`;
  $$('[data-plan]').forEach(b=>b.onclick=()=>{selected=b.dataset.plan;visited=0;placed=[];scope=selected==='spray'?100:25;renderQuest();});$('#reset').onclick=()=>{reset();$('#route-work').innerHTML='';renderQuest();};$('#commit').onclick=commit;
  if(i===0)route();if(i===1)bindBudget();if(i===2)farm();if(i===3)festival();ready();
}
function points(){return selected==='detour'?[[16,40],[34,54],[58,57],[82,50]]:selected==='corridor'?[[14,42],[38,54],[62,40],[85,30]]:selected==='garden'?[[18,44],[48,32],[79,44]]:[[15,27],[46,42],[83,55]];}
function route(){const w=$('#route-work');w.innerHTML='';if(!selected)return;const ps=points();w.innerHTML=`<svg viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true"><polyline class="route-track" points="${ps.map(p=>p.join(',')).join(' ')}"/><polyline id="route-done" points="${ps.slice(0,visited).map(p=>p.join(',')).join(' ')}"/></svg>${ps.map((p,i)=>`<button data-point="${i}" class="route-point ${i<visited?'done':''}" style="left:${p[0]}%;top:${p[1]}%" aria-label="길 지점 ${i+1}">${i+1}</button>`).join('')}`;let dragging=false;const visit=n=>{if(n!==visited)return;visited++;$$('[data-point]').forEach((b,i)=>b.classList.toggle('done',i<visited));$('#route-done').setAttribute('points',ps.slice(0,visited).map(p=>p.join(',')).join(' '));$('#task-note').textContent=`${visited}/${ps.length} 지점 연결`;ready();};$$('[data-point]').forEach(b=>{b.onclick=()=>visit(Number(b.dataset.point));b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);dragging=true;visit(Number(b.dataset.point));};});w.onpointermove=e=>{if(!dragging)return;for(const b of $$('[data-point]')){const r=b.getBoundingClientRect();if(e.clientX>=r.left-8&&e.clientX<=r.right+8&&e.clientY>=r.top-8&&e.clientY<=r.bottom+8)visit(Number(b.dataset.point));}};w.onpointerup=w.onpointercancel=()=>dragging=false;}
function draggable(el,index,accept){el.onpointerdown=e=>{if(e.button!==0)return;e.preventDefault();picked=index;const ghost=document.createElement('div');ghost.className='drag-ghost';ghost.textContent=el.textContent;document.body.append(ghost);const move=ev=>{ghost.style.left=ev.clientX+'px';ghost.style.top=ev.clientY+'px';};move(e);const clear=()=>{ghost.remove();document.removeEventListener('pointermove',move);document.removeEventListener('pointerup',up);document.removeEventListener('pointercancel',clear);};const up=ev=>{const dest=document.elementFromPoint(ev.clientX,ev.clientY)?.closest('[data-drop]');clear();if(dest){lastDrop=Date.now();accept(index,dest.dataset.drop);}};document.addEventListener('pointermove',move);document.addEventListener('pointerup',up);document.addEventListener('pointercancel',clear);};el.onclick=()=>{if(Date.now()-lastDrop<300)return;picked=index;toast('놓을 곳을 눌러 주세요.');};}
function budgetHTML(){return `<div class="token-tray">${budget.map((v,i)=>`<button class="coin ${v!==null?'used':''}" data-token="${i}" aria-label="예산 토큰 ${i+1}">✦</button>`).join('')}</div><div class="budget-bays">${seasons[1].choices.slice(0,3).map((c,i)=>`<button class="budget-bay" data-drop="${i}"><span>${['⚙','🧹','🏮'][i]}</span><div><strong>${c.name}</strong><small>${descriptions[1][i]}</small></div><b>${budget.filter(v=>v===i).length}</b></button>`).join('')}</div><small class="budget-note">한 곳에 2개 이상이면 그 대책을 실행해요.<br>1개씩 나누면 세 대책을 조금씩 시작해요.</small>`;}
function bindBudget(){const accept=(i,d)=>{budget[i]=Number(d);picked=null;renderQuest();};$$('[data-token]').filter(b=>budget[Number(b.dataset.token)]===null).forEach(b=>draggable(b,Number(b.dataset.token),accept));$$('[data-drop]').forEach(b=>b.onclick=()=>{if(Date.now()-lastDrop<300)return;const i=picked??budget.findIndex(v=>v===null);if(i>=0)accept(i,b.dataset.drop);});}
function farm(){if(!selected)return;const w=$('#work');if(['care','spray'].includes(selected)){w.innerHTML=`<div class="farm-work"><label for="scope">관리 범위 <strong id="scope-label">${scope}%</strong></label><input id="scope" type="range" min="0" max="100" step="25" value="${scope}"><small id="scope-action">실행할 방법: ${scope===0?'지켜보기':scope>=75?'전체 농약 사용':'피해 구역 살피기'}</small><div class="field-patches">${Array.from({length:8},(_,i)=>`<span class="${i<scope/100*8?'chosen':''}">🌱</span>`).join('')}</div></div>`;$('#scope').oninput=e=>{scope=Number(e.target.value);$('#scope-label').textContent=scope+'%';$('#scope-action').textContent='실행할 방법: '+(scope===0?'지켜보기':scope>=75?'전체 농약 사용':'피해 구역 살피기');$$('.field-patches span').forEach((b,i)=>b.classList.toggle('chosen',i<scope/100*8));};}}
const supplies={reuse:['컵 반납함','분리배출함','조명 담당'],once:['쓰레기봉투','청소 도구','청소 일정'],party:['일회용 컵','일회용 봉투','조명 상자'],burn:['쓰레기 모으기','태우기 제안','처리 담당']};
function festival(){if(!selected)return;$('#work').innerHTML=`<div class="supplies">${supplies[selected].map((t,i)=>`<button data-supply="${i}" class="supply ${placed.includes(i)?'placed':''}">${placed.includes(i)?'✓':'📦'} ${t}</button>`).join('')}</div><button class="festival-drop" data-drop="festival">🏮 축제장 준비 칸 <strong>${placed.length}/3</strong></button>`;const accept=i=>{if(!placed.includes(Number(i)))placed.push(Number(i));picked=null;festival();ready();};$$('[data-supply]').filter(b=>!placed.includes(Number(b.dataset.supply))).forEach(b=>draggable(b,Number(b.dataset.supply),accept));$('.festival-drop').onclick=()=>{if(Date.now()-lastDrop<300)return;const i=picked??[0,1,2].find(i=>!placed.includes(i));if(i!==undefined)accept(i);};}
function ready(){if(!$('#commit'))return;$('#commit').disabled=g().stage===0?(!selected||visited<points().length):g().stage===1?budget.some(v=>v===null):g().stage===2?!selected:(!selected||placed.length<3);}
function commit(){let id=selected;if(g().stage===1){const dominant=[0,1,2].find(i=>budget.filter(x=>x===i).length>=2);id=dominant===undefined?'share':seasons[1].choices[dominant].id;}if(g().stage===2&&['care','spray'].includes(selected))id=scope===0?'wait':scope<=50?'care':'spray';if(!seasons[g().stage].choices.some(c=>c.id===id))return;g().choices[g().stage]=id;g().phase='result';save();$('#route-work').innerHTML='';render();}
function final(){$('#quest').innerHTML=`<span class="quest-tag">겨울의 마지막 회의</span><div class="quest-portrait">🏡</div><h2>다음 봄을 앞두고</h2><p>네 계절을 지나왔어요.<br>이대로 이어 갈까요?<br>방법을 지금이라도 바꿀까요?</p><div class="final-choices"><button id="keep"><strong>지금 계획대로 진행</strong><small>고른 방법을 계속해요.</small></button><button id="repair"><strong>문제가 된 방법 고치기</strong><small>담당 어른들과 대책을 마련해요.</small></button></div><button class="text-button" id="final-journal">내 선택 기록 보기</button>`;$('#keep').onclick=()=>finish(false);$('#repair').onclick=()=>finish(true);$('#final-journal').onclick=journal;}
function finish(repair){const choices=[...g().choices],id=resolveEnding(choices,repair),fresh=!state.album[id];state.album[id]={choices,repair};state.last={choices,repair};state.game=null;save();cinema({id,choices,repair},fresh);}
function modal(title,html){const d=$('#dialog');d.innerHTML=`<div class="dialog-head"><h2>${title}</h2><button id="close" aria-label="닫기">×</button></div><div class="dialog-body">${html}</div>`;$('#close').onclick=()=>d.close();if(!d.open)d.showModal();return d;}
function recordDialog(i){if(!g()?.choices[i])return;const s=seasons[i],c=s.choices.find(c=>c.id===g().choices[i]);modal(`${icons[i]} ${s.name}의 기록`,`<p class="record-date">${s.month} · ${s.area}</p><h3>${c.name}</h3><p>${c.result}</p><span class="record-stamp">${statusFor(g().choices)[i]}</span>`);}
function journal(){const a=g()?.choices||state.last?.choices||[null,null,null,null];modal('🎒 내 모험 기록',`<div class="journal-pages">${seasons.map((s,i)=>`<button class="journal-entry ${a[i]?'written':''}" data-record="${i}"><span>${icons[i]}</span><div><strong>${s.name} · ${s.area}</strong><p>${a[i]?choiceLabel(i,a[i]):'아직 기록하지 않았어요.'}</p></div></button>`).join('')}</div><p class="small-note">이미 실행한 선택의 기록만 보여요.</p>`);$$('[data-record]').forEach(b=>b.onclick=()=>{if(g()?.choices[b.dataset.record])recordDialog(Number(b.dataset.record));else if(a[b.dataset.record]){const i=Number(b.dataset.record),c=seasons[i].choices.find(c=>c.id===a[i]);modal(`${icons[i]} ${seasons[i].name}의 기록`,`<h3>${c.name}</h3><p>${c.result}</p>`);}});}
function openAlbum(page=0){page=page===1?1:0;modal(`📖 엔딩 앨범 ${count()}/10`,`<p class="album-lead">다른 선택으로 새로운 이야기를 찾아보세요.</p><div class="album-grid">${endings.slice(page*5,page*5+5).map(e=>`<button class="ending-card ${state.album[e.id]?'found':'locked'}" data-ending="${e.id}"><span>${state.album[e.id]?'✦':'🔒'}</span><small>${e.id}</small><strong>${state.album[e.id]?e.title:'아직 펼치지 않은 이야기'}</strong></button>`).join('')}</div><div class="album-nav"><button id="prev" ${page===0?'disabled':''}>◀ 앞장</button><span>${page+1}/2</span><button id="next-page" ${page===1?'disabled':''}>다음 장 ▶</button></div>`);$('#prev').onclick=()=>openAlbum(0);$('#next-page').onclick=()=>openAlbum(1);$$('[data-ending]').forEach(b=>b.onclick=()=>albumDetail(b.dataset.ending));}
function albumDetail(id){const e=endings.find(e=>e.id===id),r=state.album[id];modal(`${id} · ${r?e.title:'새 엔딩의 단서'}`,`<p>${r?'이 이야기를 이미 발견했어요. 영화처럼 다시 볼 수 있어요.':state.last?e.hint:'첫 모험을 마치면 새 이야기의 단서를 볼 수 있어요.'}</p>${r?'<button class="primary" id="rewatch">엔딩 다시 보기</button>':''}${state.last?`<div class="replay-buttons">${seasons.map((s,i)=>`<button data-restart="${i}">${s.name}부터 다시</button>`).join('')}</div><p class="small-note">가장 최근에 끝낸 판의 앞선 선택을 남겨 둬요.</p>`:''}<button class="text-button" id="album-back">앨범으로 돌아가기</button>`);if(r)$('#rewatch').onclick=()=>cinema({id,...r});$('#album-back').onclick=()=>openAlbum(id>'E05'?1:0);$$('[data-restart]').forEach(b=>b.onclick=()=>start(Number(b.dataset.restart)));}
function cinema(r,fresh=false){
  clearInterval(cinemaTimer);$('#dialog').close();$('.cinema')?.remove();
  const e=endings.find(e=>e.id===r.id),lines=endingText(r.id,r.choices);music.setScene(e.tone);
  const c=document.createElement('section');c.className='cinema '+e.tone;
  c.innerHTML=`<div class="cinema-top"><span>초록마을 · 다음 봄</span><div>${musicUI()}<button id="cinema-save" data-cloud-status title="다른 기기로 이동하기 전에 눌러 주세요">${cloudLabel()}</button><button class="cinema-world-toggle" id="ending-world-toggle">마을만 크게 보기</button><button id="pause">잠깐 멈춤</button><button id="speed">빠르게</button><button id="all">전체 보기</button><button id="type">타이핑 다시 보기</button></div></div><div class="cinema-body"><section class="ending-world" aria-label="이 엔딩에서 내가 만든 마을"><div class="ending-world-label"><strong>내 선택이 남긴 초록마을</strong><small>${r.repair?'뒤늦은 대책도 피해를 모두 지우지는 못해요':'네 계절 동안 바뀐 풍경'}</small></div><div class="ending-world-map"><div class="world-plane">${worldSVG({choices:r.choices,ending:true,repair:r.repair,stage:4})}</div></div><div class="ending-world-records">${seasons.map((s,i)=>`<span><strong>${icons[i]} ${s.area}</strong>${choiceLabel(i,r.choices[i])}</span>`).join('')}</div></section><div class="credits-window" id="credits-window"><div class="credits"><small>ENDING ${r.id.slice(1)} / 10</small><h1>${e.title}</h1><div id="lines"></div></div></div></div><div class="cinema-bottom"><div><strong>${fresh?'새 엔딩을 발견했어요!':'다시 만난 이야기'} · ${count()}/10</strong><small>기기에 기록했어요. 기기를 바꾸기 전 ☁ 저장 버튼을 눌러 주세요.</small></div><button id="cinema-album">📖 엔딩 앨범</button><button class="primary" id="replay">다른 선택 해보기</button></div>`;
  document.body.append(c);bindMusic();$('#cinema-save').onclick=()=>$('#save-cloud').click();
  $('#ending-world-toggle').onclick=()=>{const only=c.classList.toggle('map-only');$('#ending-world-toggle').textContent=only?'이야기 함께 보기':'마을만 크게 보기';};
  let paused=false,speed=1,p=0,char=0,delay=0,element;
  const type=()=>{clearInterval(cinemaTimer);$('#lines').innerHTML='';$('#credits-window').scrollTop=0;p=0;char=0;delay=0;paused=false;speed=1;$('#pause').disabled=false;$('#speed').disabled=false;$('#pause').textContent='잠깐 멈춤';$('#speed').textContent='빠르게';element=document.createElement('p');element.className='typing';$('#lines').append(element);
    cinemaTimer=setInterval(()=>{if(paused||$('#dialog').open||c.classList.contains('map-only'))return;if(delay>0){delay-=speed;return;}char=Math.min(char+speed,lines[p].length);element.textContent=lines[p].slice(0,char);const win=$('#credits-window');win.scrollTo({top:Math.max(0,element.offsetTop+element.offsetHeight-win.clientHeight*.72),behavior:'smooth'});if(char>=lines[p].length){element.classList.remove('typing');p++;if(p===lines.length){clearInterval(cinemaTimer);$('#pause').disabled=true;return;}char=0;delay=15;element=document.createElement('p');element.className='typing';$('#lines').append(element);}},45);
  };
  $('#type').onclick=type;$('#pause').onclick=()=>{paused=!paused;$('#pause').textContent=paused?'계속 읽기':'잠깐 멈춤';};$('#speed').onclick=()=>{speed=speed===1?3:1;$('#speed').textContent=speed===1?'빠르게':'천천히';};
  $('#all').onclick=()=>{clearInterval(cinemaTimer);$('#lines').innerHTML=lines.map(s=>`<p>${H(s)}</p>`).join('');$('#credits-window').scrollTop=0;$('#pause').disabled=true;$('#speed').disabled=true;};$('#cinema-album').onclick=openAlbum;$('#replay').onclick=replayDialog;
  if(matchMedia('(prefers-reduced-motion:reduce)').matches)$('#all').click();else type();
}
function replayDialog(){modal('어느 계절부터 바꿀까요?',`<p>이전 계절의 선택을 남기고 다시 해요.<br>처음부터 하려면 봄을 골라 주세요.</p><div class="replay-buttons">${seasons.map((s,i)=>`<button data-restart="${i}">${icons[i]} ${s.name}부터</button>`).join('')}</div><p class="small-note">수집한 엔딩은 계속 남아요.</p>`);$$('[data-restart]').forEach(b=>b.onclick=()=>start(Number(b.dataset.restart)));}
function accountDialog(){const a=cloud.account();if(a){modal('☁ 내 학교 계정',`<h3>${H(a.school)} · ${H(a.nickname)}</h3><p>${cloudStatus==='conflict'?'다른 기기에 더 최근 기록이 있어요. 불러오기로 확인해 주세요.':'기기에는 바로 저장하고, 온라인에는 10분마다 묶어 저장해요. 기기를 바꾸거나 수업을 마칠 때 지금 저장하기를 눌러 주세요.'}</p><div class="account-actions"><button class="primary" id="sync">지금 저장하기</button><button id="pull">온라인 기록 불러오기</button><button id="logout">저장하고 로그아웃</button></div><p class="form-error" id="account-error"></p>`);$('#sync').onclick=async()=>{try{cloud.queueCloud(state);await cloud.flushCloud();toast('온라인 저장 완료');$('#dialog').close();}catch(e){$('#account-error').textContent=cloud.authMessage(e);}};$('#pull').onclick=async()=>{const pending={...state};try{const remote=await cloud.loadCloud();state=remote;state.album={...pending.album,...remote.album};pastChapter=null;viewMode='auto';reset();save();$('#dialog').close();render();toast('온라인 기록을 불러왔어요.');}catch(e){$('#account-error').textContent=cloud.authMessage(e);}};$('#logout').onclick=async()=>{try{cloud.queueCloud(state);await cloud.signOut();$('#dialog').close();home();}catch(e){$('#account-error').textContent='온라인 저장이 안 되어 로그아웃을 멈췄어요. 연결을 확인해 주세요.';}};return;}
  modal('🌱 학교 계정으로 모험하기',`<div class="login-tabs"><button id="login-tab" class="active">로그인</button><button id="signup-tab">처음 가입</button></div><form id="login-form"><label>학교 이름<input name="school" autocomplete="organization" maxlength="60" minlength="2" required placeholder="예: 광주 초록초등학교"></label><label>닉네임<input name="nickname" autocomplete="username" maxlength="16" minlength="2" required placeholder="실명 대신 별명을 써 주세요"></label><label>비밀번호<input name="password" type="password" autocomplete="current-password" minlength="8" maxlength="128" required placeholder="8자 이상"></label><p class="form-error" id="form-error"></p><button class="primary" type="submit" id="login-submit">로그인하고 이어 하기</button></form><p class="small-note">같은 학교·닉네임·비밀번호로 다른 기기에서도 이어 해요.<br>비밀번호를 기억해 두세요. 이메일은 받지 않아요.</p><button class="text-button" id="guest">계정 없이 체험하기</button>`);let create=false;$('#login-tab').onclick=()=>setMode(false);$('#signup-tab').onclick=()=>setMode(true);const setMode=v=>{create=v;$('#signup-tab').classList.toggle('active',v);$('#login-tab').classList.toggle('active',!v);$('#login-submit').textContent=v?'가입하고 모험 시작':'로그인하고 이어 하기';$('#login-form [name=password]').autocomplete=v?'new-password':'current-password';$('#form-error').textContent='';};$('#guest').onclick=()=>{$('#dialog').close();if(!g())start(0);};$('#login-form').onsubmit=async ev=>{ev.preventDefault();const f=new FormData(ev.currentTarget);$('#login-submit').disabled=true;$('#form-error').textContent='연결하는 중이에요…';try{await cloud.signIn({school:f.get('school'),nickname:f.get('nickname'),password:f.get('password'),create});$('#dialog').close();home();toast(create?'학교 계정이 준비되었어요.':'온라인 기록을 불러왔어요.');}catch(e){$('#form-error').textContent=cloud.authMessage(e);$('#login-submit').disabled=false;}};}
function conflictDialog(){accountDialog();}
function help(){modal('🌿 마을 모험 안내',`<div class="help-copy"><p>전체 지도에서 장소에 들어가면 그곳의 풍경과 대화가 펼쳐져요. 네 계절을 이어 가요. 지도를 누르거나 방향키로 움직일 수 있어요.</p><p>봄에는 길을 잇고, 여름에는 예산을 나누고, 가을에는 관리 범위를 정하고, 겨울에는 준비물을 배치해요. 끌기가 어려우면 물건과 놓을 곳을 차례로 눌러도 돼요.</p><p>선택의 결과는 실행한 뒤 나타나요. 실행한 선택에 따라 도로·하천·농장·축제장의 모습이 달라져요. 전체 지도에서도 변화가 남고, 이미 방문한 장소를 누르면 풍경과 기록을 다시 볼 수 있어요.</p><p>10개의 엔딩을 모아요. 앨범에는 새 엔딩의 단서가 있어요. 한 판 뒤에는 원하는 계절부터 다시 할 수 있어요.</p><p>계정으로 로그인하면 온라인에 10분마다 자동 저장해요. 기기를 바꾸기 전에는 ‘지금 저장하기’를 눌러 주세요. 공유 태블릿에서는 모험 뒤 ‘저장하고 로그아웃’을 눌러 주세요.</p><p>위쪽 소리 버튼으로 배경음악을 켜고 끌 수 있어요. 음표 버튼에서 음량을 조절해요. 결말을 만난 뒤에는 음악도 이야기 분위기에 맞게 바뀌어요.</p><p class="small-note">가상의 생태계 이야기입니다. 공사·농약·시설 관리는 담당 어른들이 합니다. 생물의 죽음을 직접 설명하는 결말이 있습니다. 배경은 AI로 제작한 일러스트입니다.</p></div>`);}
$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
cloud.onCloudStatus((status)=>{cloudStatus=status;if(status==='error'&&booting){booting=false;home();toast('온라인 연결을 확인해 주세요. 체험은 계속할 수 있어요.');}if(status==='saved')writeLocal();document.querySelectorAll('#save-cloud,[data-cloud-status]').forEach(b=>b.textContent=cloudLabel());});
home();cloud.initCloud((profile,remote)=>{booting=false;key=profile?'eco-village-'+profile.uid:'eco-village-guest-v2';const local=readLocal();let recover=false;if(profile&&remote){let base=-1;try{base=Number(localStorage.getItem(key+'-base')??-1);}catch{}recover=base===cloud.version()&&local.updatedAt>remote.updatedAt;state=recover?local:remote;const more=Object.keys(local.album).some(id=>!state.album[id]);state.album={...local.album,...state.album};recover ||= more;writeLocal();}else state=local;cloudStatus=profile?'online':'guest';reset();home();if(recover){cloud.queueCloud(state);toast('이 기기에 남은 기록도 이어서 저장해요.');}}).catch(()=>{booting=false;cloudStatus='error';home();toast('온라인 연결이 어려워요. 체험은 계속할 수 있어요.');});
